    // 1. Check for NULL pointers
    if ((wheels == NULL) || (field == NULL) || (momentum == NULL) || 
        (command == NULL) || (torque == NULL) || (energy == NULL) || (dissipation == NULL)) {
        momentum->x = 0.0; momentum->y = 0.0; momentum->z = 0.0;
        command->command->x = 0.0; command->command->y = 0.0; command->command->z = 0.0;
        command->saturated_axes = 0U;
        torque->x = 0.0; torque->y = 0.0; torque->z = 0.0;
        *energy = 0.0;
        *dissipation = 0.0;
        return ADCS_E_NULL;
    }

    // 2. Check count range [1..16] and field finiteness
    if ((count < 1) || (count > 16) || (!adcs_is_finite_vec3(field))) {
        momentum->x = 0.0; momentum->y = 0.0; momentum->z = 0.0;
        command->command->x = 0.0; command->command->y = 0.0; command->command->z = 0.0;
        command->saturated_axes = 0U;
        torque->x = 0.0; torque->y = 0.0; torque->z = 0.0;
        *energy = 0.0;
        *dissipation = 0.0;
        return ADCS_E_RANGE;
    }

    // 3. Compute cluster momentum
    adcs_status_t status = adcs_wheel_momentum(wheels, count, momentum);
    if (status != ADCS_OK) {
        momentum->x = 0.0; momentum->y = 0.0; momentum->z = 0.0;
        command->command->x = 0.0; command->command->y = 0.0; command->command->z = 0.0;
        command->saturated_axes = 0U;
        torque->x = 0.0; torque->y = 0.0; torque->z = 0.0;
        *energy = 0.0;
        *dissipation = 0.0;
        return ADCS_E_RANGE;
    }

    // 4. Compute stored wheel energy: sum_i(0.5 * J_i * omega_i^2)
    double total_energy = 0.0;
    for (size_t i = 0; i < count; ++i) {
        double j = wheels[i].inertia_kg_m2;
        double w = wheels[i].speed_rad_s;
        total_energy += 0.5 * j * w * w;
    }
    *energy = total_energy;

    // 5. Request bounded magnetic unloading command
    status = adcs_momentum_unload_dipole(momentum, field, gain, dipole_limit, command, torque);
    if (status != ADCS_OK) {
        momentum->x = 0.0; momentum->y = 0.0; momentum->z = 0.0;
        command->command->x = 0.0; command->command->y = 0.0; command->command->z = 0.0;
        command->saturated_axes = 0U;
        torque->x = 0.0; torque->y = 0.0; torque->z = 0.0;
        *energy = 0.0;
        *dissipation = 0.0;
        return status;
    }

    // 6. Report dissipation: dot(momentum, torque)
    *dissipation = adcs_vec3_dot(momentum, torque);

    return ADCS_OK;
}

